#!/system/bin/sh
# SPDX-License-Identifier: BSD-2-Clause-Patent
# Run only from the bundle generated by partition.py, stored in recovery RAM.
set -eu
cd "$(dirname "$0")"

stop() { echo "STOP: $*" >&2; exit 1; }
[ "$(id -u)" = 0 ] || stop 'root recovery required'
[ -n "$(getprop ro.twrp.version)" ] || stop 'TWRP required'
[ "$(getprop sys.boot_completed)" != 1 ] || stop 'Android is running'
for command in sha256sum cmp dd blockdev readlink sync umount; do
    command -v "$command" >/dev/null || stop "missing command: $command"
done
sha256sum -c SHA256SUMS || stop 'bundle changed or upload incomplete'
. ./plan.env
[ "$(uname -r)" = "$KERNEL" ] || stop 'kernel changed since planning'
serial=$(getprop ro.serialno)
[ -n "$serial" ] || serial=$(getprop ro.boot.serialno)
[ "$serial" = "$HARDWARE_SERIAL" ] || stop 'wrong device'
[ "$(readlink -f /dev/block/by-name/userdata)" = "$RAW" ] || stop 'userdata path changed'
[ "$(blockdev --getsize64 "$DISK")" = "$DISK_BYTES" ] || stop 'disk size changed'
[ "$(blockdev --getss "$DISK")" = "$SECTOR" ] || stop 'sector size changed'
[ "$(blockdev --getsize64 "$RAW")" = "$OLD_BYTES" ] || stop 'userdata size changed'
[ "$(cat "/sys/class/block/${RAW##*/}/start")" = "$USER_START_512" ] || stop 'userdata start changed'

compare_gpt() {
    dd if="$DISK" of=primary.read bs="$SECTOR" count="$PRIMARY_BLOCKS" 2>/dev/null
    dd if="$DISK" of=backup.read bs="$SECTOR" skip="$BACKUP_LBA" count="$BACKUP_BLOCKS" 2>/dev/null
    cmp primary.read "gpt-primary.$1" || stop 'primary GPT differs'
    cmp backup.read "gpt-backup.$1" || stop 'backup GPT differs'
}

case "${1:-check}" in
    check)
        compare_gpt before
        ./f2fs-shrink probe "$RAW"
        echo 'CHECK OK; no filesystem or GPT writes'
        exit 0
        ;;
    apply)
        [ "${2:-}" = "$CONFIRM" ] || stop 'explicit device/size confirmation required'
        [ ! -e started ] || stop 'an apply already started; inspect state before recovery'
        ;;
    *) stop 'usage: sh twrp.sh check | apply "SERIAL unixnu BYTES"' ;;
esac

compare_gpt before
# A second invocation must not retry a partially completed resize or GPT write.
mkdir /tmp/unixnu-dual.lock || stop 'another apply started in this recovery session; inspect its state'
mkdir started || stop 'another apply is running'
echo 'F2FS resize started' > stage
./f2fs-shrink shrink "$RAW" "$OLD_BYTES" "$OLD_BLOCKS" "$LIMIT_BLOCKS"
echo 'F2FS resize verified; GPT still original' > stage
sync
# Unmount normally: open files or bind mounts must stop the procedure.
umount /data || stop 'cannot unmount /data; GPT unchanged, do not force or use lazy unmount'
./f2fs-shrink offline "$RAW" "$OLD_BYTES" "$EXPECTED_BLOCKS" "$LIMIT_BLOCKS" "$MAPPED"
compare_gpt before

# Update the backup first. Keep MBR and all untouched partition entries byte-identical.
echo 'Writing backup GPT' > stage
dd if=gpt-backup.after of="$DISK" bs="$SECTOR" seek="$BACKUP_LBA" conv=notrunc
sync
dd if="$DISK" of=backup.read bs="$SECTOR" skip="$BACKUP_LBA" count="$BACKUP_BLOCKS" 2>/dev/null
cmp backup.read gpt-backup.after || stop 'backup GPT readback failed; do not reboot'
echo 'Backup GPT verified; writing primary GPT' > stage
dd if=gpt-primary.after of="$DISK" bs="$SECTOR" conv=notrunc
sync
compare_gpt after
echo 'GPT complete and read back' > stage
echo 'DONE: leave /data unmounted. Reboot into recovery to refresh partition and encryption mappings.'
echo 'Do not format userdata or unixnu. Run host verify after recovery restarts.'
